patch_result.patch:
--- a/valid.c
+++ b/valid.c
@@ -2510,6 +2510,7 @@
 int
 xmlRemoveID(xmlDocPtr doc, xmlAttrPtr attr) {
     xmlIDTablePtr table;
+    const xmlChar *id;

     if (doc == NULL) return(-1);
     if ((attr == NULL) || (attr->id == NULL)) return(-1);
@@ -2518,12 +2519,17 @@
     if (table == NULL)
         return(-1);

-    if (xmlHashRemoveEntry(table, attr->id->value, xmlFreeIDTableEntry) < 0)
-        return(-1);
-
+    id = attr->id->value;
     attr->atype = 0;
     attr->id = NULL;

+    if (xmlHashRemoveEntry(table, id, xmlFreeIDTableEntry) < 0) {
+        attr->id = xmlHashLookup(table, id);
+        if (attr->id != NULL)
+            attr->atype = XML_ATTRIBUTE_ID;
+        return(-1);
+    }
+
     return(0);
 }

args:
@@ -2511,18 +2511,24 @@
 xmlRemoveID(xmlDocPtr doc, xmlAttrPtr attr) {
     xmlIDTablePtr table;
+    const xmlChar *id;

     if (doc == NULL) return(-1);
     if ((attr == NULL) || (attr->id == NULL)) return(-1);

     table = (xmlIDTablePtr) doc->ids;
     if (table == NULL)
         return(-1);
+
+    id = attr->id->value;
+    attr->atype = 0;
+    attr->id = NULL;

-    if (xmlHashRemoveEntry(table, attr->id->value, xmlFreeIDTableEntry) < 0)
+    if (xmlHashRemoveEntry(table, id, xmlFreeIDTableEntry) < 0) {
+        attr->id = xmlHashLookup(table, id);
+        if (attr->id != NULL)
+            attr->atype = XML_ATTRIBUTE_ID;
         return(-1);
-
-    attr->atype = 0;
-    attr->id = NULL;
+    }

     return(0);
 }
